  matrix_base::matrix_base (size_t rows, size_t cols) :
      data (NULL)
  {
    data = new double[rows * cols];
    this->rows = rows;
    this->cols = cols;
  }

  matrix_base::~matrix_base ()
  {
    if (data)
      delete[] data;
  }

  void
  matrix_base::clear ()
  {
    for (size_t i = 0; i < rows; i++)
      for (size_t j = 0; j < cols; j++)
	pos (i, j) = 0.;
  }
 

